// An orbital poster from circles, ellipses and lines. The array order is the
// paint order: sky first, then the sunburst, orbits, sun, planets and type.
const W = 1080, H = 1350, cx = 540, cy = 600;
let seed = 7;
const rand = () => {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const r2 = (n) => Math.round(n * 100) / 100;
const stop = (offset, color, opacity = 1) => ({ name: "stop", attributes: { offset, "stop-color": color, "stop-opacity": opacity } });

const defs = {
  name: "defs",
  children: [
    { name: "clipPath", attributes: { id: "above" }, children: [{ name: "rect", attributes: { x: 0, y: 0, width: W, height: 1060 } }] },
    { name: "radialGradient", attributes: { id: "sky", cx: "50%", cy: "44%", r: "75%" }, children: [stop("0%", "#2a1b4d"), stop("55%", "#120d2b"), stop("100%", "#06060f")] },
    { name: "radialGradient", attributes: { id: "sun", cx: "38%", cy: "34%", r: "70%" }, children: [stop("0%", "#fff4d6"), stop("35%", "#ffb347"), stop("70%", "#ff5e3a"), stop("100%", "#c2185b")] },
    { name: "radialGradient", attributes: { id: "glow", cx: "50%", cy: "50%", r: "50%" }, children: [stop("0%", "#ff7a45", 0.55), stop("60%", "#ff3d7f", 0.12), stop("100%", "#ff3d7f", 0)] },
    { name: "linearGradient", attributes: { id: "ring", x1: "0%", y1: "0%", x2: "100%", y2: "100%" }, children: [stop("0%", "#7dd3fc"), stop("100%", "#c084fc")] },
    { name: "radialGradient", attributes: { id: "teal", cx: "35%", cy: "30%", r: "70%" }, children: [stop("0%", "#ccfbf1"), stop("60%", "#14b8a6"), stop("100%", "#0f3d48")] },
    { name: "radialGradient", attributes: { id: "violet", cx: "35%", cy: "30%", r: "70%" }, children: [stop("0%", "#f5d0fe"), stop("60%", "#a855f7"), stop("100%", "#3b0764")] },
    { name: "radialGradient", attributes: { id: "ice", cx: "35%", cy: "30%", r: "70%" }, children: [stop("0%", "#ffffff"), stop("60%", "#93c5fd"), stop("100%", "#1e3a8a")] }
  ]
};

const elements = [defs, { name: "rect", attributes: { x: 0, y: 0, width: W, height: H, fill: "url(#sky)" } }];

// Stars: tiny circles scattered over the sky.
for (let i = 0; i < 160; i++) {
  elements.push({ name: "circle", attributes: { cx: r2(rand() * W), cy: r2(rand() * H * 0.9), r: r2(0.6 + rand() * 1.6), fill: "#ffffff", opacity: r2(0.15 + rand() * 0.6) } });
}

// Sunburst: lines radiating from the centre, painted under everything else
// and clipped to the sky above the horizon.
const burst = { name: "g", attributes: { "clip-path": "url(#above)" }, children: [] };
elements.push(burst);
for (let i = 0; i < 120; i++) {
  const a = (i / 120) * Math.PI * 2;
  const inner = 210, outer = 330 + rand() * 300;
  burst.children.push({ name: "line", attributes: {
    x1: r2(cx + Math.cos(a) * inner), y1: r2(cy + Math.sin(a) * inner),
    x2: r2(cx + Math.cos(a) * outer), y2: r2(cy + Math.sin(a) * outer),
    stroke: i % 3 === 0 ? "#ffb347" : "#7dd3fc", "stroke-width": i % 3 === 0 ? 1.6 : 0.8, opacity: r2(0.12 + rand() * 0.3)
  } });
}

// Concentric rings with dashes that tighten towards the sun.
for (let i = 0; i < 9; i++) {
  const r = 200 + i * 38;
  elements.push({ name: "circle", attributes: {
    cx, cy, r, fill: "none", stroke: "url(#ring)", "stroke-width": i === 4 ? 2 : 1,
    "stroke-dasharray": i % 2 ? `${2 + i} ${6 + i * 2}` : "none", opacity: r2(0.55 - i * 0.05)
  } });
}

// Tilted orbits, each an ellipse with a planet riding on it.
const orbits = [
  { rx: 470, ry: 120, tilt: -18, planet: 0.18, size: 30, fill: "url(#teal)" },
  { rx: 400, ry: 170, tilt: 24, planet: 0.62, size: 22, fill: "url(#violet)" },
  { rx: 330, ry: 90, tilt: -48, planet: 0.86, size: 14, fill: "url(#ice)" },
  { rx: 520, ry: 230, tilt: 8, planet: 0.4, size: 18, fill: "url(#ice)" }
];
for (const o of orbits) {
  elements.push({ name: "ellipse", attributes: { cx, cy, rx: o.rx, ry: o.ry, fill: "none", stroke: "#e0e7ff", "stroke-width": 1.2, opacity: 0.45, transform: `rotate(${o.tilt} ${cx} ${cy})` } });
}

// The sun: a soft halo, then the disc, then a thin rim.
elements.push({ name: "circle", attributes: { cx, cy, r: 300, fill: "url(#glow)" } });
elements.push({ name: "circle", attributes: { cx, cy, r: 170, fill: "url(#sun)" } });
elements.push({ name: "circle", attributes: { cx, cy, r: 178, fill: "none", stroke: "#ffd9a8", "stroke-width": 1.5, opacity: 0.6 } });

// Planets go after the sun so they pass in front of it.
for (const o of orbits) {
  const a = o.planet * Math.PI * 2, t = (o.tilt * Math.PI) / 180;
  const ex = Math.cos(a) * o.rx, ey = Math.sin(a) * o.ry;
  const px = cx + ex * Math.cos(t) - ey * Math.sin(t), py = cy + ex * Math.sin(t) + ey * Math.cos(t);
  elements.push({ name: "circle", attributes: { cx: r2(px), cy: r2(py), r: o.size * 2.2, fill: "#ffffff", opacity: 0.06 } });
  elements.push({ name: "circle", attributes: { cx: r2(px), cy: r2(py), r: o.size, fill: o.fill } });
}

// Horizon: a fan of lines converging on the vanishing point.
for (let i = -12; i <= 12; i++) {
  elements.push({ name: "line", attributes: { x1: cx, y1: 1060, x2: cx + i * 90, y2: H, stroke: "#7dd3fc", "stroke-width": 1, opacity: r2(0.35 - Math.abs(i) * 0.02) } });
}
for (let i = 0; i < 7; i++) {
  const y = 1060 + Math.pow(i / 6, 1.8) * (H - 1060);
  elements.push({ name: "line", attributes: { x1: 0, y1: r2(y), x2: W, y2: r2(y), stroke: "#c084fc", "stroke-width": 1, opacity: r2(0.15 + i * 0.05) } });
}
elements.push({ name: "line", attributes: { x1: 0, y1: 1060, x2: W, y2: 1060, stroke: "#ffb347", "stroke-width": 2, opacity: 0.8 } });

// Type sits on top of everything.
const type = { "font-family": "Inter, 'Helvetica Neue', Arial, sans-serif", fill: "#f8fafc" };
elements.push({ name: "text", attributes: { ...type, x: 72, y: 128, "font-size": 88, "font-weight": 800, "letter-spacing": -2 }, content: "Circles" });
elements.push({ name: "text", attributes: { ...type, x: 72, y: 212, "font-size": 88, "font-weight": 300, "letter-spacing": -2, fill: "#ffb347" }, content: "& Lines" });
elements.push({ name: "text", attributes: { ...type, x: 1008, y: 104, "font-size": 18, "font-weight": 600, "letter-spacing": 4, "text-anchor": "end", opacity: 0.7 }, content: "ORBITAL STUDY Nº 7" });
elements.push({ name: "text", attributes: { ...type, x: 1008, y: 132, "font-size": 18, "letter-spacing": 4, "text-anchor": "end", opacity: 0.45 }, content: "SVG · 1080 × 1350" });

return { output: elements };
